<?php
if(!defined('ABSPATH')){exit;}
final class Orion_Catalogue_Audit{
 public function run(int $limit=0):array{if(!function_exists('wc_get_products'))return array('summary'=>array('error'=>'WooCommerce is not active.'),'issue_counts'=>array(),'severity_counts'=>array(),'issues'=>array());$ids=array_map('absint',wc_get_products(array('status'=>'publish','return'=>'ids','limit'=>$limit>0?min(5000,$limit):-1,'orderby'=>'ID','order'=>'ASC')));$issues=array();$sku_map=array();$title_map=array();$variable=0;$variations=0;foreach($ids as$id){$p=wc_get_product($id);if(!$p)continue;$name=$p->get_name();$short=trim(wp_strip_all_tags($p->get_short_description()));$description=trim(wp_strip_all_tags($p->get_description()));$cats=$this->categories($id);$attrs=$this->attributes($p);$identity=strtolower(html_entity_decode($name.' '.implode(' ',$cats),ENT_QUOTES|ENT_HTML5,'UTF-8'));$text=strtolower(html_entity_decode($identity.' '.$short.' '.$description.' '.wp_json_encode($attrs),ENT_QUOTES|ENT_HTML5,'UTF-8'));$title_key=$this->normalise_title($name);if($title_key!=='')$title_map[$title_key][]=$id;$sku=trim((string)$p->get_sku());if($sku==='')$this->issue($issues,$id,$name,$p->is_type('variable')?'missing_parent_sku':'missing_sku',$p->is_type('variable')?'info':'warning',$p->is_type('variable')?'Variable parent has no SKU; verify that every variation has a unique SKU.':'Product has no SKU.');else$sku_map[strtolower($sku)][]=$id;if($short===''&&$description==='')$this->issue($issues,$id,$name,'missing_description','critical','Product has no description for customer or AI suitability checks.');elseif(mb_strlen($short.' '.$description)<80)$this->issue($issues,$id,$name,'short_description','warning','Combined description is under 80 characters.');if(!array_filter($cats,static fn($v)=>strtolower((string)$v)!=='uncategorized'))$this->issue($issues,$id,$name,'missing_category','critical','Product has no useful category.');if(!$p->get_image_id())$this->issue($issues,$id,$name,'missing_image','warning','Product has no featured image.');if($p->is_type('variable')){$variable++;$children=$p->get_children();if(!$children){$this->issue($issues,$id,$name,'broken_variable_product','critical','Variable product has no variations and cannot provide a purchasable price or option.');}else foreach($children as$child_id){$v=wc_get_product($child_id);if(!$v)continue;$variations++;if($v->get_price()==='')$this->issue($issues,$id,$name,'variation_missing_price','critical','Variation #'.$child_id.' has no price.',$child_id);$vsku=trim((string)$v->get_sku());if($vsku==='')$this->issue($issues,$id,$name,'variation_missing_sku','warning','Variation #'.$child_id.' has no SKU.',$child_id);else$sku_map[strtolower($vsku)][]=$child_id;$vattrs=$v->get_variation_attributes();if(!$vattrs||!array_filter($vattrs,static fn($value)=>trim((string)$value)!==''))$this->issue($issues,$id,$name,'variation_missing_attributes','warning','Variation #'.$child_id.' has no selected attributes.',$child_id);}}elseif($p->get_price()==='')$this->issue($issues,$id,$name,'missing_price','critical','Simple product has no active price.');if($this->is_application_material($identity)&&!$this->is_accessory_or_hardware($identity)&&!preg_match('/\b(floor|wall|ceiling|exterior|external|outdoor|interior|internal|masonry|concrete|wood|timber|metal|plaster|brick|roof|tile|bathroom|kitchen|garage|multi[- ]?surface|all surface|universal)\b/',$text))$this->issue($issues,$id,$name,'suitability_unknown','warning','Material description does not establish a surface or use environment.');if(preg_match('/\b(floor|garage|epoxy)\b/',$text)&&preg_match('/walls? and ceilings?|walls? only|ceilings? only/',$text)&&!preg_match('/suitable for[^.]{0,100}\bfloor/',$text))$this->issue($issues,$id,$name,'suitability_conflict','critical','Floor-related product text conflicts with wall/ceiling-only suitability.');}foreach($sku_map as$sku=>$entity_ids)if(count(array_unique($entity_ids))>1)foreach(array_unique($entity_ids)as$entity_id){$parent_id=wp_get_post_parent_id($entity_id)?:$entity_id;$p=wc_get_product($parent_id);$this->issue($issues,$parent_id,$p?$p->get_name():'','duplicate_sku','critical','SKU "'.$sku.'" is used by IDs '.implode(', ',array_unique($entity_ids)).'.',$entity_id!==$parent_id?$entity_id:0);}foreach($title_map as$title=>$product_ids)if(count(array_unique($product_ids))>1)foreach(array_unique($product_ids)as$id){$p=wc_get_product($id);$this->issue($issues,$id,$p?$p->get_name():'','duplicate_title','warning','Normalised title is also used by product IDs '.implode(', ',array_unique($product_ids)).'.');}$counts=array_count_values(array_column($issues,'code'));ksort($counts);$severity=array_count_values(array_column($issues,'severity'));foreach(array('critical','warning','info')as$level)if(!isset($severity[$level]))$severity[$level]=0;$affected_by=array();foreach($issues as$issue)$affected_by[$issue['severity']][$issue['product_id']]=true;$critical_products=count($affected_by['critical']??array());$warning_products=count($affected_by['warning']??array());$info_products=count($affected_by['info']??array());$affected=count(array_unique(array_column($issues,'product_id')));$ai_codes=array('missing_description','short_description','missing_category','suitability_unknown','suitability_conflict','broken_variable_product','missing_price','variation_missing_price');$ai_affected=array();foreach($issues as$issue)if(in_array($issue['code'],$ai_codes,true))$ai_affected[$issue['product_id']]=true;$total=count($ids);return array('summary'=>array('products_checked'=>$total,'variable_products'=>$variable,'variations_checked'=>$variations,'products_with_issues'=>$affected,'critical_products'=>$critical_products,'warning_products'=>$warning_products,'info_products'=>$info_products,'operational_ready_products'=>max(0,$total-$critical_products),'operational_readiness_percent'=>$total?round(($total-$critical_products)/$total*100,1):0,'ai_ready_products'=>max(0,$total-count($ai_affected)),'ai_readiness_percent'=>$total?round(($total-count($ai_affected))/$total*100,1):0,'total_issues'=>count($issues)),'issue_counts'=>$counts,'severity_counts'=>$severity,'issues'=>$issues);}
 private function issue(array &$issues,int $product_id,string $name,string $code,string $severity,string $message,int $variation_id=0):void{$issues[]=array('product_id'=>$product_id,'variation_id'=>$variation_id,'product'=>$name,'code'=>$code,'severity'=>$severity,'message'=>$message);}private function is_application_material(string $identity):bool{return(bool)preg_match('/\b(paint|primer|undercoat|coating|varnish|stain|sealer|sealant|silicone|caulk|filler|adhesive|mortar|render|plaster|grout|levelling compound|leveling compound)\b/',$identity);}private function is_accessory_or_hardware(string $identity):bool{return(bool)preg_match('/\b(roller|sleeve|frame|brush|tray|tape|dust sheet|protection sheet|glove|ppe|coverall|screw|fixing|tool|scraper|wrench|spirit level|blade|bit|sandpaper|steel wool|cord|fire seal|weather strip|wallpaper stripper|storage system|vapour mate|roller set|painting pack)\b/',$identity);}private function normalise_title(string $title):string{$title=strtolower(html_entity_decode(wp_strip_all_tags($title),ENT_QUOTES|ENT_HTML5,'UTF-8'));$title=preg_replace('/[^a-z0-9]+/',' ',remove_accents($title));return trim((string)preg_replace('/\s+/',' ',$title));}private function categories(int $id):array{$cats=wp_get_post_terms($id,'product_cat',array('fields'=>'names'));return is_wp_error($cats)?array():array_values(array_map('strval',$cats));}private function attributes(WC_Product $p):array{$out=array();foreach($p->get_attributes()as$a){$name=$a->get_name();$values=$a->is_taxonomy()?wc_get_product_terms($p->get_id(),$name,array('fields'=>'names')):$a->get_options();$out[$name]=is_wp_error($values)?array():$values;}return$out;}
}
